function renderTrackGeometryEditor(){const host=document.querySelector('#settings-tab .settings-grid');if(!host||!state.geography)return;let card=document.getElementById('track-geometry-editor');if(!card){card=document.createElement('section');card.id='track-geometry-editor';card.className='card track-geometry-card';host.append(card);}const segs=state.geography.segments||{};card.innerHTML='<h2>Track Geometry</h2><p class="warning">Explicit rail segments, control points, and named turnout endpoints. No proximity joins.</p>'+Object.entries(segs).map(([id,s])=>`<div class="geometry-row"><strong>${esc(id)}</strong> <span>${esc(s.start)} → ${esc(s.end)} · ${(s.points||[]).length} control points</span><button data-geom="${esc(id)}">Split</button></div>`).join('')+'<button id="validate-track-geometry">Validate graph</button><pre id="track-geometry-result"></pre>';card.querySelectorAll('[data-geom]').forEach(b=>b.onclick=()=>{const id=b.dataset.geom,s=segs[id],mid=Math.floor(s.points.length/2);if(mid<1||mid>=s.points.length-1)return;const a={...s,points:s.points.slice(0,mid+1),end:`${id}_split`},c={...s,points:s.points.slice(mid),start:`${id}_split`};delete segs[id];segs[`${id}_a`]=a;segs[`${id}_b`]=c;renderTrackGeometryEditor();drawCenterlines();});document.getElementById('validate-track-geometry').onclick=async()=>{const r=await (await fetch('/api/geography')).json();document.getElementById('track-geometry-result').textContent=(r.graph_valid?'Graph endpoints valid':'Graph incomplete')+'\n'+(r.graph_errors||[]).join('\n');};}
function geometrySnapshot(){return JSON.parse(JSON.stringify({segments:state.geography.segments,junctions:state.geography.junctions,terminals:state.geography.terminals,connections:state.geography.connections,yard_tracks:state.geography.yard_tracks}));}
function geometryPushUndo(){state.geometryUndo=state.geometryUndo||[];state.geometryUndo.push(geometrySnapshot());if(state.geometryUndo.length>30)state.geometryUndo.shift();}
async function geometrySave(){const payload=geometrySnapshot();const r=await (await fetch('/api/track-geometry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})).json();if(!r.saved)throw Error(r.error||'geometry validation failed');state.geometrySaved=payload;state.geometryUndo=[];renderGeometryEditor();}
function geometryCancel(){if(state.geometrySaved)Object.assign(state.geography,state.geometrySaved);state.geometryEdit=false;state.geometryUndo=[];drawCenterlines();renderGeometryEditor();}
function geometryReset(){const id=state.selectedSegment,s=state.geography.segments?.[id];if(!s||!state.geometrySaved?.segments?.[id])return;geometryPushUndo();state.geography.segments[id].points=JSON.parse(JSON.stringify(state.geometrySaved.segments[id].points));drawCenterlines();renderGeometryEditor();}
function renderGeometryEditor(){let p=document.getElementById('dashboard-geometry-editor');if(!p)return;p.hidden=!state.geometryEdit;if(!state.geometryEdit){drawCenterlines();return;}const segs=state.geography.segments||{},ids=Object.keys(segs);if(!state.selectedSegment||!segs[state.selectedSegment])state.selectedSegment=ids[0];const id=state.selectedSegment,s=segs[id],junctions=Object.keys(state.geography.junctions||{}),terms=state.geography.terminals||[],ends=junctions.concat(terms);p.innerHTML=`<div class="geometry-editor-head"><strong>Edit Geometry</strong><span>${esc(id)}</span></div><label>Segment<select id="geometry-segment">${ids.map(v=>`<option ${v===id?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="geometry-editor-buttons"><button id="geometry-prev">Previous Segment</button><button id="geometry-next">Next Segment</button></div><div class="geometry-info">Track system: <b>${esc(s.track_path||'unassigned')}</b><br>Endpoints: <b>${esc(s.start)} → ${esc(s.end)}</b><br>Connected turnouts: <b>${esc((state.geography.connections||[]).filter(c=>c.from?.startsWith(id+':')||c.to?.startsWith(id+':')).map(c=>c.via||'—').join(', ')||'none')}</b></div><label>Point<select id="geometry-point">${(s.points||[]).map((_,i)=>`<option value="${i}">Control point ${i+1}</option>`).join('')}</select></label><div class="geometry-editor-buttons"><button id="geometry-add">Add Point</button><button id="geometry-delete">Delete Point</button></div><label>START endpoint<select id="geometry-start">${ends.map(v=>`<option ${v===s.start?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>END endpoint<select id="geometry-end">${ends.map(v=>`<option ${v===s.end?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="geometry-editor-buttons"><button id="geometry-undo">Undo</button><button id="geometry-reset">Reset Segment</button><button id="geometry-save" class="primary-button">Save</button><button id="geometry-cancel">Cancel</button></div><div id="geometry-warning" class="warning">${state.geography.graph_valid?'No graph validation errors reported.':'Graph warnings: '+(state.geography.graph_errors||[]).join('; ')}</div>`;const select=id=>document.getElementById(id);select('geometry-segment').onchange=e=>{state.selectedSegment=e.target.value;renderGeometryEditor();drawCenterlines()};select('geometry-point').onchange=e=>state.selectedPoint=Number(e.target.value);select('geometry-start').onchange=e=>{geometryPushUndo();s.start=e.target.value;renderGeometryEditor();drawCenterlines()};select('geometry-end').onchange=e=>{geometryPushUndo();s.end=e.target.value;renderGeometryEditor();drawCenterlines()};select('geometry-prev').onclick=()=>{state.selectedSegment=ids[(ids.indexOf(id)-1+ids.length)%ids.length];renderGeometryEditor();drawCenterlines()};select('geometry-next').onclick=()=>{state.selectedSegment=ids[(ids.indexOf(id)+1)%ids.length];renderGeometryEditor();drawCenterlines()};select('geometry-add').onclick=()=>{geometryPushUndo();const pts=s.points, i=Math.min(Number(select('geometry-point').value)||0,pts.length-2),a=pts[i],b=pts[i+1];pts.splice(i+1,0,[(a[0]+b[0])/2,(a[1]+b[1])/2]);state.selectedPoint=i+1;renderGeometryEditor();drawCenterlines()};select('geometry-delete').onclick=()=>{if(s.points.length<=2)return;geometryPushUndo();s.points.splice(Math.max(0,Number(select('geometry-point').value)||0),1);renderGeometryEditor();drawCenterlines()};select('geometry-undo').onclick=()=>{const old=(state.geometryUndo||[]).pop();if(old){state.geography.segments=old.segments;state.geography.junctions=old.junctions;state.geography.terminals=old.terminals;state.geography.connections=old.connections;state.geography.yard_tracks=old.yard_tracks;renderGeometryEditor();drawCenterlines()}};select('geometry-reset').onclick=geometryReset;select('geometry-save').onclick=()=>geometrySave().catch(e=>select('geometry-warning').textContent=e.message);select('geometry-cancel').onclick=geometryCancel;}
function ensureDashboardGeometryEditor(){if(!document.querySelector('.map-tools')||!state.geography)return;let b=document.getElementById('edit-geometry');if(!b){b=document.createElement('button');b.id='edit-geometry';b.textContent='Edit Geometry';document.querySelector('.map-tools').prepend(b);b.onclick=()=>{state.geometryEdit=!state.geometryEdit;if(state.geometryEdit&&!state.geometrySaved)state.geometrySaved=geometrySnapshot();b.textContent=state.geometryEdit?'Close Editor':'Edit Geometry';b.classList.toggle('primary-button',state.geometryEdit);renderGeometryEditor();drawCenterlines();};}let p=document.getElementById('dashboard-geometry-editor');if(!p){p=document.createElement('div');p.id='dashboard-geometry-editor';p.className='geometry-editor-panel';p.hidden=true;document.querySelector('.map-footer').after(p);}renderGeometryEditor();}
const $=id=>document.getElementById(id),svgNS='http://www.w3.org/2000/svg';
setInterval(()=>{if(typeof state!=='undefined'&&state.geography){ensureDashboardGeometryEditor();if(!state.geometryEdit&&document.getElementById('show-centerlines')){document.getElementById('show-centerlines').checked=false;drawCenterlines();}if(!document.getElementById('settings-tab')?.hidden)renderTrackGeometryEditor()}},500);
const state={status:null,zones:[],boundaries:{},geography:null,config:null,calibration:null,commandedSpeeds:{},commandedDirections:{},speedUpdateTimers:{},scale:1,x:0,y:0,drag:null,dragMarker:null,editorZone:null,showLabels:false,geometryEdit:false,selectedSegment:null,selectedPoint:0,geometryUndo:[],geometrySaved:null};
function ensureLabelToggle(){if($('show-zone-labels'))return;const lines=document.createElement('label');lines.innerHTML='<input id="show-centerlines" type="checkbox" checked> Centerlines';const labels=document.createElement('label');labels.innerHTML='<input id="show-zone-labels" type="checkbox"> Labels';const snap=document.createElement('label');snap.innerHTML='<input id="snap-markers" type="checkbox" checked> Snap to path';const status=document.createElement('span');status.id='calibration-status';status.className='centerline-status';status.textContent='Centerline proposals · unverified';document.querySelector('.map-footer').prepend(lines,snap,labels,status);$('show-centerlines').onchange=drawCenterlines;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))} function fmt(v){return v==null?'—':v}
function setTab(name){document.querySelectorAll('.nav-tab,.side-link').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.tab-panel').forEach(p=>{p.hidden=p.id!==name+'-tab';p.classList.toggle('active',p.id===name+'-tab')});if(name==='settings')renderSettings();}
function markerGroup(zone,kind,point){const g=document.createElementNS(svgNS,'g');g.className.baseVal='zone-marker';g.dataset.markerKind='zone';g.dataset.zone=zone;g.dataset.kind=kind;const info=state.geography?.zones?.[zone]?.[kind==='start'?'start_geometry':'end_geometry'];if(info){g.dataset.alignmentError=info.alignment_error_px;if(info.alignment_error_px>12)g.classList.add('unaligned');}const x=point[0]*752,y=point[1]*602;const c=document.createElementNS(svgNS,'circle');c.setAttribute('cx',x);c.setAttribute('cy',y);c.setAttribute('r',5);const t=document.createElementNS(svgNS,'text');t.setAttribute('x',x+8);t.setAttribute('y',y-7);t.textContent=state.showLabels?`${zone} ${kind.toUpperCase()}`:'';g.append(c,t);g.addEventListener('pointerdown',e=>{state.dragMarker={kind:'zone',zone,endpoint:kind};e.stopPropagation();});return g;}
function decorateOverlayMarkers(){const geo=state.geography||{};[...$('checkpoint-layer').children].forEach((g,i)=>{const r=(geo.ir_receivers||[])[i];if(r){g.dataset.markerKind='receiver';g.dataset.markerId=r.id;if(r.geometry?.alignment_error_px>12)g.classList.add('unaligned');g.onpointerdown=e=>{state.dragMarker={kind:'receiver',id:r.id};e.stopPropagation();};}});Object.entries(geo.turnouts||{}).forEach(([id,v],i)=>{const g=$('turnout-layer').children[i];if(g){g.dataset.markerKind='turnout';g.dataset.markerId=id;if(v.geometry?.alignment_error_px>12)g.classList.add('unaligned');g.onpointerdown=e=>{state.dragMarker={kind:'turnout',id};e.stopPropagation();};}});}
function snapPoint(point){const geo=state.geography||{};const candidates=[...(geo.ir_receivers||[]).map(r=>r.position),...Object.values(geo.turnouts||{}).map(r=>r.position)].filter(Boolean);let best=null;for(const q of candidates){const d=Math.hypot(point[0]-q[0],point[1]-q[1]);if(d<.018&&(!best||d<best.d))best={d,p:q};}return best?best.p:point;}
function drawCenterlines(){const svg=$('overlay'),layer=$('centerline-layer')||document.createElementNS(svgNS,'g');layer.id='centerline-layer';if(!layer.parentNode)svg.prepend(layer);layer.innerHTML='';if(!state.geometryEdit&&!$('show-centerlines')?.checked)return;Object.entries(state.geography?.segments||{}).forEach(([id,seg])=>{if(state.geometryEdit&&state.selectedSegment&&id!==state.selectedSegment)return;const line=document.createElementNS(svgNS,'polyline');line.className.baseVal='track-segment';line.dataset.segment=id;line.setAttribute('points',(seg.points||[]).map(p=>`${p[0]},${p[1]}`).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke',seg.color||'#fff');line.setAttribute('stroke-width',state.geometryEdit?'5':'3');line.setAttribute('stroke-dasharray','7 5');layer.append(line);if(state.geometryEdit)(seg.points||[]).forEach((p,i)=>{const c=document.createElementNS(svgNS,'circle');c.className.baseVal='control-point';c.dataset.segment=id;c.dataset.index=i;c.setAttribute('cx',p[0]);c.setAttribute('cy',p[1]);c.setAttribute('r',i===state.selectedPoint?'6':'4');c.addEventListener('pointerdown',e=>{state.selectedSegment=id;state.selectedPoint=i;state.dragControl={segment:id,index:i};e.stopPropagation()});layer.append(c)});});}
function projectPath(segment,point){let best=null,run=0;for(let i=0;i<segment.points.length-1;i++){const a=segment.points[i],b=segment.points[i+1],ux=b[0]-a[0],uy=b[1]-a[1],len=Math.hypot(ux,uy);if(!len)continue;const t=Math.max(0,Math.min(1,((point[0]-a[0])*ux+(point[1]-a[1])*uy)/(len*len))),q=[a[0]+t*ux,a[1]+t*uy],d=Math.hypot(point[0]-q[0],point[1]-q[1]);if(!best||d<best.error)best={segment_id:segment.id,distance_px:run+t*len,point:q,error:d};run+=len;}return best;}
function snapPoint(point){const geo=state.geography||{};const candidates=[...(geo.ir_receivers||[]).map(r=>r.position),...Object.values(geo.turnouts||{}).map(r=>r.position)].filter(Boolean);let best=null;for(const q of candidates){const d=Math.hypot(point[0]-q[0],point[1]-q[1]);if(d<.018&&(!best||d<best.d))best={d,p:q};}return best?best.p:point;}
function drawOverlay(){const s=state.status||{},sim=s.simulation||{},geo=state.geography||{};const cl=$('checkpoint-layer');cl.innerHTML='';if($('show-checkpoints').checked)(geo.ir_receivers||[]).forEach(r=>{if(!r.position)return;const g=document.createElementNS(svgNS,'g');g.className.baseVal='checkpoint';const c=document.createElementNS(svgNS,'circle');c.setAttribute('cx',r.position[0]*752);c.setAttribute('cy',r.position[1]*602);c.setAttribute('r',5);const t=document.createElementNS(svgNS,'text');t.setAttribute('x',r.position[0]*752+8);t.setAttribute('y',r.position[1]*602+4);t.textContent=state.showLabels?r.name:'';g.append(c,t);cl.append(g)});const tl=$('turnout-layer');tl.innerHTML='';if($('show-turnouts').checked)Object.entries(geo.turnouts||{}).forEach(([id,r])=>{if(!r.position)return;const g=document.createElementNS(svgNS,'g');g.className.baseVal='turnout';const c=document.createElementNS(svgNS,'circle');c.setAttribute('cx',r.position[0]*752);c.setAttribute('cy',r.position[1]*602);c.setAttribute('r',7);const t=document.createElementNS(svgNS,'text');t.setAttribute('x',r.position[0]*752+9);t.setAttribute('y',r.position[1]*602+4);t.textContent=state.showLabels?id:'';g.append(c,t);tl.append(g)});const zl=$('zone-marker-layer');zl.innerHTML='';if($('show-zone-markers').checked)Object.entries(state.boundaries).forEach(([id,b])=>{if(b.start)zl.append(markerGroup(id,'start',b.start));if(b.end)zl.append(markerGroup(id,'end',b.end));});const tr=$('train-layer');tr.innerHTML='';if(sim.geometry_available)(s.trains||[]).forEach(t=>{const p=sim.trains?.[String(t.id)]?.position;if(!p)return;const g=document.createElementNS(svgNS,'g');g.className.baseVal='locomotive '+(s.global_stop?'stopped':'');const c=document.createElementNS(svgNS,'circle');c.setAttribute('cx',p[0]*752);c.setAttribute('cy',p[1]*602);c.setAttribute('r',12);const label=document.createElementNS(svgNS,'text');label.setAttribute('x',p[0]*752);label.setAttribute('y',p[1]*602+5);label.setAttribute('text-anchor','middle');label.textContent=t.id;g.append(c,label);tr.append(g)});}
function renderDashboard(){const s=state.status||{},sim=s.simulation||{};$('global-stop-banner').hidden=!s.global_stop;$('global-stop-reason').textContent=s.stop_reason||'All simulated movement has been stopped.';$('last-update').textContent='Updated '+new Date().toLocaleTimeString();$('connection-text').textContent='Controller connected';$('connection-dot').className='status-dot ok';const trains=s.trains||[];$('train-cards').innerHTML=trains.map(t=>{const st=sim.trains?.[String(t.id)]||{};return `<div class="train-row"><div class="train-id"><span class="train-dot ${st.speed_mm_s?'':'stopped'}"></span>${esc(t.name)} <span class="sim-chip">#${t.id}</span></div><div class="train-meta">${esc(t.type)} · ${st.speed_mm_s?st.speed_mm_s+' mm/s':'stopped'}<br>${esc(t.destination||'No destination')} · ${sim.geometry_available?'simulated path':'position unavailable'}</div></div>`}).join('');const yp=s.yard_power||{};$('yard-power').innerHTML=[['1','Stalls 1A + 1B'],['2','Stall 2'],['3','Stall 3']].map(([id,label])=>`<div class="yard-row"><div>${label}<div class="yard-power-bar"><span style="width:${yp[id]?'100':'0'}%"></span></div></div><div class="yard-meta">${yp[id]?'ON':'OFF'}<br><span class="sim-chip">simulated</span></div></div>`).join('');$('turnout-summary').innerHTML=Object.entries(s.turnouts||{}).map(([id,v])=>`<span class="turnout-pill"><strong>${id}</strong> ${esc(v)}</span>`).join('');const zones=s.zones||{},res=s.reservations||{};$('zone-grid').innerHTML=state.zones.map(z=>{const occ=zones[z.id],r=res[z.id];return `<div class="zone-cell ${occ?'occupied':''} ${!occ&&r?'reserved':''}"><div class="zone-name">${z.id}</div><div class="zone-state">${occ?'Train '+occ+' occupied':r?'Reserved · Train '+r:'Clear · simulation'}</div></div>`}).join('');$('zone-summary').textContent=`${state.zones.length} configured · ${Object.values(zones).filter(Boolean).length} occupied · unverified topology`;$('boundary-preview').innerHTML=Object.entries(state.boundaries).map(([id,b])=>`<div class="boundary-chip"><strong>${id}</strong><br><span class="marker-key">START</span> ${b.start?b.start.map(v=>v.toFixed(3)).join(', '):'uncalibrated'} · <span class="marker-key">END</span> ${b.end?b.end.map(v=>v.toFixed(3)).join(', '):'uncalibrated'}</div>`).join('');drawOverlay();decorateOverlayMarkers();renderRoutes();renderSimulation();}
function renderRoutes(){const trains=(state.status||{}).trains||[];$('route-trains').innerHTML=trains.map(t=>{const d=t.type==='passenger'?'Ski':(t.destination||'Yard');return `<article class="route-train"><div class="card-heading"><h3>${esc(t.name)} <span class="sim-chip">${esc(t.type)}</span></h3></div><div class="field-row"><label class="field-label">Destination<select><option ${d==='Yard'?'selected':''}>Yard</option><option ${d==='Ski'?'selected':''}>Ski</option><option>Town</option><option>Mine</option><option>Farm</option><option>Tipper</option></select></label><label class="field-label">Dwell seconds<input type="number" min="0" value="30"></label></div><label class="field-label cycle-field">Programmed cycle<input value="${esc((t.cycle||[]).join(' → '))}" placeholder="Mine → Tipper → Yard"></label></article>`}).join('');}
function renderSimulation(){const sim=(state.status||{}).simulation||{};$('geometry-status').textContent=sim.geometry_available?'Verified surveyed paths loaded':'Awaiting verified surveyed paths';$('simulation-note').textContent=sim.geometry_available?'Paths are calibrated; coordinates follow stored centerlines.':'Movement is disabled until surveyed centerlines are calibrated and marked verified. No arbitrary shortcut animation is used.';$('calibration-state').textContent=state.calibration?.verified?'VERIFIED':'UNVERIFIED';$('simulation-event-log').innerHTML=(sim.events||[]).slice().reverse().map(e=>`<div><span>${Number(e.time).toFixed(2)}s</span> ${esc(e.event)} ${esc(JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k])=>!['time','event'].includes(k)))) )}</div>`).join('')||'<div class="subtle">No simulation events yet.</div>';}
function optionList(values,current){return [current,...values].filter((v,i,a)=>v&&a.indexOf(v)===i).map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function renderSettings(){if(!state.config)return;const rows=state.config.io||[],devices=['Raspberry Pi GPIO','MCP23017','PCA9685','Arduino Nano IR'],locations=['Raspberry Pi','Raspberry Pi I2C','unassigned',...state.zones.map(z=>z.id)],functions=['general-purpose I/O','IR receiver','Hall sensor','turnout','yard power','motor output','servo output'];$('io-table').querySelector('tbody').innerHTML=rows.map(r=>`<tr><td><select>${optionList(devices,r.device)}</select></td><td><input value="${esc(r.io)}"></td><td><select>${optionList(locations,r.location)}</select></td><td><select>${optionList(functions,r.function)}</select></td><td><select><option ${r.polarity==='active_high'?'selected':''}>active_high</option><option ${r.polarity==='active_low'?'selected':''}>active_low</option><option ${r.polarity==='n/a'?'selected':''}>n/a</option></select></td><td>${esc(r.status)}</td></tr>`).join('');$('calibration-list').innerHTML=(state.config.locomotives||[]).map(t=>`<div class="calibration-row"><span>${esc(t.name)}</span><span>speed ${fmt(t.speed_mm_s_at_255)} · braking ${fmt(t.braking_mm)}</span></div>`).join('');$('controller-config').innerHTML=Object.entries(state.config.controller||{}).map(([k,v])=>`<div class="config-row"><span>${esc(k)}</span><span>${esc(v)}</span></div>`).join('');$('editor-zone').innerHTML=state.zones.map(z=>`<option value="${z.id}">${z.id} · ${esc(z.railway)}</option>`).join('');if(!state.editorZone)state.editorZone=state.zones[0]?.id;$('editor-zone').value=state.editorZone;loadEditorMarkers();$('calibration-json').value=JSON.stringify(state.calibration||{verified:false,paths:{}},null,2);}
function loadEditorMarkers(){const b=state.boundaries[state.editorZone]||{};$('start-x').value=b.start?.[0]??'';$('start-y').value=b.start?.[1]??'';$('end-x').value=b.end?.[0]??'';$('end-y').value=b.end?.[1]??'';}function readMarkers(){return {start:[Number($('start-x').value),Number($('start-y').value)],end:[Number($('end-x').value),Number($('end-y').value)]}}
function setTransform(){$('map-content').style.transform=`translate(${state.x}px,${state.y}px) scale(${state.scale})`;}function fit(){const v=$('map-viewport'),s=Math.min(v.clientWidth/752,v.clientHeight/602);state.scale=Math.max(s,.2);state.x=(v.clientWidth-752*state.scale)/2;state.y=(v.clientHeight-602*state.scale)/2;setTransform();}
async function command(action,extra={}){const d=await (await fetch('/api/simulation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...extra})})).json();if(!d.ok)throw Error(d.error||'command failed');return d;}
async function load(){try{const [sr,zr,br,cr,cal,geo]=await Promise.all(['/api/status','/api/zones','/api/zone-boundaries','/api/config','/api/simulation/calibration','/api/geography'].map(u=>fetch(u)));state.status=await sr.json();state.zones=(await zr.json()).zones;state.boundaries=(await br.json()).boundaries;state.config=await cr.json();state.calibration=await cal.json();state.geography=await geo.json();renderDashboard();renderSettings();fit();}catch(e){$('connection-text').textContent='Controller unavailable';$('connection-dot').className='status-dot bad';console.error(e);}}
async function refresh(){try{state.status=await (await fetch('/api/status')).json();renderDashboard();}catch(e){$('connection-text').textContent='Controller unavailable';$('connection-dot').className='status-dot bad';}}
async function saveMarkers(){const m=readMarkers();if([...m.start,...m.end].some(v=>!Number.isFinite(v)||v<0||v>1)){$('editor-result').textContent='Invalid normalized markers.';return}const d=await (await fetch('/api/zones/boundaries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone_id:state.editorZone,...m})})).json();$('editor-result').textContent=d.saved?'Saved endpoint pair; still uncalibrated until physical calibration.':d.error;if(d.saved){state.boundaries[state.editorZone]={...state.boundaries[state.editorZone],...m,calibrated:false};renderDashboard();}}
async function saveCalibration(){try{const d=JSON.parse($('calibration-json').value),r=await (await fetch('/api/simulation/calibration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)})).json();$('calibration-result').textContent=r.ok?'Calibration saved. Geometry available: '+r.geometry_available:r.error;await refresh();}catch(e){$('calibration-result').textContent=e.message;}}
