async function saveDraggedMarker(){const m=state.dragMarker;if(!m)return;if(m.kind==='zone'){const b=state.boundaries[m.zone];if(b?.start&&b?.end)await fetch('/api/zones/boundaries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({zone_id:m.zone,start:b.start,end:b.end})});}else{const item=m.kind==='receiver'?state.geography.ir_receivers.find(v=>v.id===m.id):state.geography.turnouts[m.id];if(item?.position){const raw=[item.position[0]*752,item.position[1]*602];const path=state.geography.centerlines[item.geometry?.track_path];const projected=path?{track_path:item.geometry.track_path,segment_id:item.geometry.segment_id,distance_px:item.geometry.distance_px,alignment_error_px:item.geometry.alignment_error_px}:null;await fetch('/api/geography/marker',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:m.kind,id:m.id,position:item.position,geometry:projected})});}}}
function wire(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));document.querySelectorAll('[data-tab-jump]').forEach(b=>b.onclick=()=>setTab(b.dataset.tabJump));['show-checkpoints','show-turnouts','show-zone-markers'].forEach(id=>$(id).onchange=drawOverlay);$('show-zone-labels').onchange=e=>{state.showLabels=e.target.checked;drawOverlay()};$('zoom-in').onclick=()=>{state.scale*=1.2;setTransform()};$('zoom-out').onclick=()=>{state.scale/=1.2;setTransform()};$('zoom-reset').onclick=fit;$('fullscreen').onclick=()=>$('map-viewport').requestFullscreen();$('map-viewport').onwheel=e=>{e.preventDefault();state.scale*=e.deltaY<0?1.1:.9;setTransform()};$('map-viewport').onpointerdown=e=>{state.drag={x:e.clientX-state.x,y:e.clientY-state.y};$('map-viewport').classList.add('dragging')};window.onpointermove=e=>{if(state.dragMarker){const rect=$('map-viewport').getBoundingClientRect(),p=[(e.clientX-rect.left-state.x)/(752*state.scale),(e.clientY-rect.top-state.y)/(602*state.scale)],b=state.boundaries[state.dragMarker.zone]||(state.boundaries[state.dragMarker.zone]={});b[state.dragMarker.kind]=p;drawOverlay();if(state.editorZone===state.dragMarker.zone)loadEditorMarkers();}else if(state.drag){state.x=e.clientX-state.drag.x;state.y=e.clientY-state.drag.y;setTransform()}};window.onpointerup=()=>{state.drag=null;state.dragMarker=null;$('map-viewport').classList.remove('dragging')};window.onresize=fit;$('global-stop-button').onclick=()=>command('global_stop',{reason:'operator global stop'}).then(refresh);$('clear-stop').onclick=()=>command('clear_stop').then(refresh).catch(e=>$('global-stop-reason').textContent=e.message);$('sim-start').onclick=()=>command('start').catch(e=>$('simulation-note').textContent=e.message);$('sim-pause').onclick=()=>command('pause');$('sim-resume').onclick=()=>command('resume').catch(e=>$('simulation-note').textContent=e.message);$('sim-reset').onclick=()=>command('reset');$('sim-speed').onchange=()=>command('speed',{multiplier:Number($('sim-speed').value)});$('inject-fault').onclick=()=>command('fault',{fault:$('fault-type').value});$('editor-zone').onchange=e=>{state.editorZone=e.target.value;loadEditorMarkers()};$('save-boundary').onclick=saveMarkers;$('cancel-boundary').onclick=loadEditorMarkers;$('reset-boundary').onclick=()=>{$('start-x').value='';$('start-y').value='';$('end-x').value='';$('end-y').value='';$('editor-result').textContent='Cleared locally; save to persist uncalibrated endpoints.'};$('validate-boundary').onclick=()=>{const m=readMarkers();$('editor-result').textContent=[...m.start,...m.end].every(v=>Number.isFinite(v)&&v>=0&&v<=1)?'Valid normalized pair; still uncalibrated.':'Invalid normalized pair.'};$('save-calibration').onclick=saveCalibration;$('validate-calibration').onclick=()=>{try{const d=JSON.parse($('calibration-json').value);$('calibration-result').textContent=Object.values(d.paths||{}).every(p=>p.points?.length>=2&&p.length_mm>0)?'Valid structure; physical survey still required.':'Each path needs two points and positive length_mm.'}catch(e){$('calibration-result').textContent=e.message}};$('save-settings').onclick=()=>{$('editor-result').textContent='Simulation settings are browser-only; no hardware outputs changed.'};}
