async function command(action,extra={}){const endpoint=hardwareMode()&&['global_stop','clear_stop','rearm'].includes(action)?'/api/control':'/api/simulation';const d=await (await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...extra})})).json();if(!d.ok)throw Error(d.error||'command failed');return d;}
