ensureLabelToggle();wire();window.onpointermove=e=>{if(state.dragControl){const rect=$('map-viewport').getBoundingClientRect(),g=state.geography.segments[state.dragControl.segment],p=[(e.clientX-rect.left-state.x)/state.scale,(e.clientY-rect.top-state.y)/state.scale];g.points[state.dragControl.index]=p;drawCenterlines();}else if(state.dragMarker){const rect=$('map-viewport').getBoundingClientRect();moveDraggedMarker([(e.clientX-rect.left-state.x)/(752*state.scale),(e.clientY-rect.top-state.y)/(602*state.scale)]);}else if(state.drag){state.x=e.clientX-state.drag.x;state.y=e.clientY-state.drag.y;setTransform();}};window.onpointerup=async()=>{if(state.dragControl){await fetch('/api/track-geometry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({segments:state.geography.segments,junctions:state.geography.junctions,terminals:state.geography.terminals,connections:state.geography.connections,yard_tracks:state.geography.yard_tracks})});state.dragControl=null;}if(state.dragMarker)await saveDraggedMarker();state.drag=null;state.dragMarker=null;$('map-viewport').classList.remove('dragging');};load().then(()=>{state.boundaries=Object.fromEntries(Object.entries(state.geography.zones).map(([id,z])=>[id,{start:z.start,end:z.end,start_geometry:z.start_geometry,end_geometry:z.end_geometry,calibrated:z.calibrated}]));drawCenterlines();renderDashboard();});setInterval(refresh,1000);setInterval(()=>{$('clock').textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})},1000);
