function ensureDispatchPanel(){const tab=$('routes-tab');if(!tab)return;let card=$('dispatch-card');if(!card){card=document.createElement('section');card.id='dispatch-card';card.className='card dispatch-card';card.innerHTML='<div class="card-heading"><div><h2>Dispatch train</h2><span class="subtle">Assign a destination in the Pi dispatcher; this does not issue a motion command.</span></div><span id="dispatch-safety-status" class="safety-badge">DISARMED</span></div><div class="dispatch-controls"><label class="field-label">Train<select id="dispatch-train"></select></label><label class="field-label">Destination<select id="dispatch-destination"><option>Yard</option><option>Ski</option><option>Town</option><option>Mine</option><option>Farm</option><option>Tipper</option><option>Turntable</option></select></label><button id="dispatch-assign" class="primary-button">Assign destination</button></div><pre id="dispatch-result" aria-live="polite"></pre>';tab.prepend(card);$('dispatch-assign').onclick=async()=>{const result=$('dispatch-result');result.textContent='Assigning destination…';try{const response=await fetch('/api/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'assign_destination',train_id:Number($('dispatch-train').value),destination:$('dispatch-destination').value})});const data=await response.json();if(!data.ok)throw Error(data.error||'assignment rejected');state.status=data.status;result.textContent='Destination assigned. No motion command issued.';renderDashboard();}catch(e){result.textContent='Assignment blocked: '+e.message;}};}const trains=(state.status||{}).trains||[],train=$('dispatch-train'),dest=$('dispatch-destination');if(train){const old=train.value;train.innerHTML=trains.map(t=>`<option value="${t.id}">${esc(t.name)} · ${esc(t.type)}</option>`).join('');if(trains.some(t=>String(t.id)===old))train.value=old;const selected=trains.find(t=>String(t.id)===train.value);if(selected?.destination&&[...dest.options].some(o=>o.value===selected.destination))dest.value=selected.destination;}const safety=$('dispatch-safety-status');if(safety){const blocked=state.status?.global_stop||!state.status?.motion_armed;safety.textContent=blocked?'DISARMED':'READY';safety.className='safety-badge '+(blocked?'':'armed');}}
const _legacyRenderRoutes=renderRoutes;renderRoutes=function(){_legacyRenderRoutes();ensureDispatchPanel();};
