function renderReferenceIoRows(){const table=$('io-table');if(!table||!document.querySelector('#settings-tab').dataset.ioReferenceLayout)return;const type=r=>/IR/i.test(r[2])?'IR Sensor':/Hall/i.test(r[2])?'Hall Sensor':/encoder/i.test(r[2])?'Encoder':/relay/i.test(r[2])?'Relay':/motor/i.test(r[2])?'Motor':/transmitter/i.test(r[2])?'IR Transmitter':/MCP/i.test(r[2])?'I/O Expander':/PCA/i.test(r[2])?'PWM Driver':'Controller I/O';const direction=r=>/output|motor|relay|transmitter/i.test(`${r[2]} ${r[3]}`)?'OUTPUT':'INPUT';table.querySelector('tbody').innerHTML=knownHardwareIo.map(r=>`<tr><td>${esc(r[1].replace(/^.*?GPIO|^.*?\/ /,''))}</td><td>${direction(r)}</td><td>${type(r)}</td><td>${esc(r[2])}</td><td>${esc(r[4].replace('_',' ').toUpperCase())}</td><td>${esc(r[5].replace('_',' '))}</td></tr>`).join('')}
